    "# Simple 2-layer network\\n",
    "W1 = np.array([[0.5, -0.3]])\\n",
    "b1 = np.array([0.1])\\n",
    "W2 = np.array([[1.0]])\\n",
    "b2 = np.array([0.0])\\n",
    "\\n",
    "x = np.array([1.0, 2.0])\\n",
    "\\n",
    "# Forward\\n",
    "z1 = W1 @ x + b1\\n",
    "a1 = np.maximum(0, z1)\\n",
    "s = W2 @ a1 + b2\\n",
    "\\n",
    "# Backward (gradient w.r.t input)\\n",
    "# ds/da1 = W2 = 1.0\\n",
    "# da1/dz1 = 1 if z1 > 0 else 0\\n",
    "# dz1/dx = W1\\n",
    "relu_mask = (z1 > 0).astype(float)\\n",
    "dscore_dx = W1.T * (W2.T * relu_mask)\\n",
